param([ValidateSet('baseline','compare-current','baseline-next','compare-next','collect','inspect')][string]$Action)
$ErrorActionPreference='Stop'
if($env:COMPUTERNAME -ne 'MU-CLEAN-LAB' -or (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion').EditionID -ne 'IoTEnterpriseSEval'){throw 'Only the dedicated Windows evaluation guest may run upgrade diagnostics'}
$sid=(Get-LocalUser MuLabUser).SID.Value;$root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$sid)
if($Action -eq 'inspect'){return @{registrations=@(Get-ChildItem -LiteralPath ('Registry::HKEY_USERS\\'+$sid+'\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall') -ErrorAction SilentlyContinue|Get-ItemProperty|Where-Object{$_.DisplayName -like 'MuCodeSandbox Windows Preview*'}|Select-Object DisplayName,DisplayVersion,UninstallString);installedFiles=$(if(Test-Path -LiteralPath C:\MuLab\public\upgrade-installed){@(Get-ChildItem -LiteralPath C:\MuLab\public\upgrade-installed -Force|Select-Object Name,Length)}else{$null});trace=$(if(Test-Path -LiteralPath C:\MuLab\public\upgrade-installer-trace.log){Get-Content -LiteralPath C:\MuLab\public\upgrade-installer-trace.log -Tail 16|Out-String}else{$null});installers=@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -like 'C:\MuLab\upgrade-payload\*' -or $_.Name -like 'ns*.tmp'}|Select-Object ProcessId,ExecutablePath,CommandLine);vms=@(Get-VM|Select-Object Name,@{Name='state';Expression={[string]$_.State}});clients=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'"|Where-Object{$_.CommandLine -like '*client.mjs*upgrade-*'}|Select-Object ProcessId,CreationDate);results=@(Get-ChildItem -LiteralPath C:\MuLab\public -Filter 'upgrade-*-result.json'|ForEach-Object{Get-Content -LiteralPath $_.FullName -Raw|ConvertFrom-Json})}}
$seed=Get-Content -LiteralPath C:\MuLab\approved\upgrade-seed-result.json -Raw|ConvertFrom-Json;if(-not $seed.complete -or -not $seed.nested.stopped){throw 'The actual prior-version VM must be prepared and stopped first'}
$id=[string]$seed.nested.config.id;if(([guid]$id).ToString('D') -cne $id){throw 'Diagnostic environment identity changed'};$disk=Join-Path $root ('vms/'+$id+'/disk.vhdx')
if($Action -eq 'collect'){
 $results=@{};foreach($phase in @('upgrade-seed','upgrade-current','upgrade-current-check','upgrade-next','upgrade-next-check','upgrade-reject','upgrade-final')){$r=Get-Content -LiteralPath ('C:\MuLab\approved\'+$phase+'-result.json') -Raw|ConvertFrom-Json;if(-not $r.complete -or $phase -ne 'upgrade-seed' -and ($r.nested.id -ne $id -or $r.nested.platformId -ne $seed.nested.platformId)){throw ('Incomplete or unrelated upgrade result: '+$phase)};$results[$phase]=$r}
 if(-not $results['upgrade-final'].nested.removed -or @(Get-VM).Count -or (Test-Path -LiteralPath (Split-Path $disk))){throw 'Synthetic VM cleanup is incomplete'}
 $primary=[IO.File]::ReadAllText((Join-Path $root vms.json));if($primary -cne [IO.File]::ReadAllText((Join-Path $root vms.backup.json)) -or @((ConvertFrom-Json $primary).records.PSObject.Properties).Count){throw 'Protected registrations must be empty and matching'}
 foreach($name in @('compare-current','compare-next')){$receipt=Get-Content -LiteralPath ('C:\MuLab\approved\upgrade-'+$name+'.json') -Raw|ConvertFrom-Json;if(-not $receipt.originalDiskUnchanged){throw 'Original disk preservation was not independently confirmed'}}
 $winlogon='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon';if((Get-ItemProperty -LiteralPath $winlogon).DefaultUserName -ne 'MuLabUser'){throw 'Synthetic logon account changed'};Remove-ItemProperty -LiteralPath $winlogon -Name DefaultPassword -ErrorAction SilentlyContinue;Set-ItemProperty -LiteralPath $winlogon -Name AutoAdminLogon -Value '0' -Type String;Set-ItemProperty -LiteralPath $winlogon -Name AutoLogonCount -Value 0 -Type DWord
 return @{results=$results;sourceHashes=@{'client'=(Get-FileHash C:\MuLab\client.mjs).Hash.ToLowerInvariant();'upgrade-client'=(Get-FileHash C:\MuLab\upgrade-client.mjs).Hash.ToLowerInvariant()};packages=(Get-Content -LiteralPath C:\MuLab\approved\upgrade-packages.json -Raw|ConvertFrom-Json);originalCanaryPreserved=$true;originalDiskUnchangedDuringInstall=$true;nestedGuestsRemaining=0;syntheticAutologonDisabled=$true;aiWebsitesVisited=0}
}
$vms=@(Get-VM -ErrorAction Stop);if($vms.Count -ne 1 -or [string]$vms[0].Id -ne $seed.nested.platformId -or $vms[0].State -ne 'Off' -or $vms[0].Name -ne ('mu-win-'+$id.Replace('-','')) -or $vms[0].Notes -ne ('MuCodeSandbox Windows preview '+$vms[0].Name)){throw 'Only the original stopped synthetic VM may be checked'}
$drives=@(Get-VMHardDiskDrive -VM $vms[0]);if($drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne [IO.Path]::GetFullPath($disk) -or (Get-Item -LiteralPath $disk).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Original disk attachment changed'}
$hash=(Get-FileHash -LiteralPath $disk).Hash.ToLowerInvariant();$saved=@{id=$id;platformId=$seed.nested.platformId;sha256=$hash;stopped=$true}
if($Action -in @('compare-current','compare-next')){$baseline=if($Action -eq 'compare-current'){'baseline'}else{'baseline-next'};$before=Get-Content -LiteralPath ('C:\MuLab\approved\upgrade-'+$baseline+'.json') -Raw|ConvertFrom-Json;if($before.id -ne $id -or $before.platformId -ne $seed.nested.platformId -or $before.sha256 -ne $hash){throw 'Installer changed the original stopped disk'};$saved.originalDiskUnchanged=$true}
[IO.File]::WriteAllText(('C:\MuLab\approved\upgrade-'+$Action+'.json'),($saved|ConvertTo-Json -Compress));return $saved
